solution_code:
#include <iostream>

class Item {
public:
    int price;
    int quantity;
};

int subtotal(const Item& it) {
    return it.price * it.quantity;
}

int main() {
    int n;
    std::cin >> n;
    int grandTotal = 0;
    for (int i = 0; i < n; ++i) {
        int p, q;
        std::cin >> p >> q;
        Item it{ p, q };
        int s = subtotal(it);
        grandTotal += s;
        std::cout << "Subtotal: " << s << "\n";
    }
    std::cout << "Total: " << grandTotal << "\n";
    return 0;
}

