solution_code:
#include <iostream>
#include <iomanip>

class Time {
public:
    int hours;
    int minutes;
};

int toMinutes(const Time& t) {
    return t.hours * 60 + t.minutes;
}

int main() {
    int n;
    std::cin >> n;
    int total = 0;
    for (int i = 0; i < n; ++i) {
        int h, m;
        std::cin >> h >> m;
        Time t{ h, m };
        int mins = toMinutes(t);
        total += mins;
        std::cout << "Minutes: " << mins << "\n";
    }
    std::cout << "Total: " << total / 60 << ":"
              << std::setfill('0') << std::setw(2) << total % 60 << "\n";
    return 0;
}
